DROP TABLE IF EXISTS `wp_dev_engine_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wp_dev_engine_logs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `ability_name` varchar(191) COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `mcp_method` varchar(50) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `api_endpoint` varchar(255) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `session_id` varchar(64) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `user_id` bigint unsigned DEFAULT '0',
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `request_params` text COLLATE utf8mb4_unicode_520_ci,
  `request_body` longtext COLLATE utf8mb4_unicode_520_ci,
  `response_data` longtext COLLATE utf8mb4_unicode_520_ci,
  `response_status` varchar(20) COLLATE utf8mb4_unicode_520_ci DEFAULT 'success',
  `execution_time_ms` int unsigned DEFAULT '0',
  `risk_level` varchar(20) COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_ability` (`ability_name`),
  KEY `idx_created` (`created_at`),
  KEY `idx_user` (`user_id`),
  KEY `idx_session` (`session_id`),
  KEY `idx_risk` (`risk_level`)
) ENGINE=InnoDB AUTO_INCREMENT=1461 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;
